pageCss:
  :root{
--ink:#1A2740;
--paper:#FAF9F6;
--paper-dim:#F1EEE6;
--brick:#8B2635;
--gold:#B5902A;
--rule:#D8D3C4;
--body-text:#3A3A34;
  }

  *{ box-sizing:border-box; }

  html{ scroll-behavior:smooth; }

  body{
margin:0;
background:var(--paper);
color:var(--body-text);
font-family:'Newsreader', Georgia, serif;
font-size:19px;
line-height:1.65;
-webkit-font-smoothing:antialiased;
  }

  .meta-face{
font-family:'IBM Plex Sans', sans-serif;
  }

  .page{
max-width:680px;
margin:0 auto;
padding:0 24px 96px;
  }

  /* Masthead */
  header.masthead{
display:flex;
align-items:baseline;
justify-content:space-between;
padding:40px 0 18px;
  }

  .wordmark{
font-family:'IBM Plex Sans', sans-serif;
font-weight:600;
font-size:15px;
color:var(--ink);
letter-spacing:0.01em;
  }

  .doc-type{
font-family:'IBM Plex Sans', sans-serif;
font-weight:500;
font-size:13px;
color:var(--brick);
  }

  hr.rule{
border:none;
border-top:1.5px solid var(--ink);
margin:0 0 28px;
  }

  hr.rule-thin{
border:none;
border-top:1px solid var(--rule);
margin:44px 0;
  }

  .date-line{
font-family:'IBM Plex Sans', sans-serif;
font-size:14px;
color:#6B6B62;
margin-bottom:10px;
  }

  h1{
font-family:'Newsreader', Georgia, serif;
font-weight:500;
font-size:2.6rem;
line-height:1.12;
color:var(--ink);
margin:0 0 18px;
letter-spacing:-0.01em;
opacity:0;
animation:rise 0.7s ease-out forwards;
  }

  @keyframes rise{
from{ opacity:0; transform:translateY(10px); }
to{ opacity:1; transform:translateY(0); }
  }

  @media (prefers-reduced-motion: reduce){
h1{ animation:none; opacity:1; }
  }

  .dek{
font-size:1.15rem;
font-style:italic;
color:#5A5A50;
margin:0 0 8px;
max-width:60ch;
  }

  article p{
margin:0 0 22px;
max-width:64ch;
  }

  article a{
color:var(--brick);
text-decoration-thickness:1px;
text-underline-offset:3px;
  }

  article a:hover{ color:var(--ink); }

  article a:focus-visible,
  button:focus-visible{
outline:2px solid var(--gold);
outline-offset:3px;
  }

  strong{ color:var(--ink); font-weight:600; }

  /* The Ask block */
  .the-ask{
margin:36px 0 40px;
padding-left:22px;
border-left:3px solid var(--gold);
  }

  .the-ask h2{
font-family:'IBM Plex Sans', sans-serif;
font-weight:600;
font-size:13px;
letter-spacing:0.03em;
color:var(--brick);
margin:0 0 18px;
text-transform:none;
  }

  .ask-item{
margin:0 0 20px;
max-width:58ch;
  }

  .ask-item:last-child{ margin-bottom:0; }

  .ask-item .who{
display:block;
font-family:'IBM Plex Sans', sans-serif;
font-weight:600;
font-size:15px;
color:var(--ink);
margin-bottom:3px;
  }

  /* Footer */
  footer{
margin-top:48px;
  }

  .disclaimer{
font-family:'IBM Plex Sans', sans-serif;
font-size:13px;
line-height:1.6;
color:#7A7A70;
font-style:normal;
max-width:60ch;
  }

  .org-line{
font-family:'IBM Plex Sans', sans-serif;
font-weight:600;
font-size:14px;
color:var(--ink);
margin-top:36px;
  }

  .org-line span{
display:block;
font-weight:400;
color:#6B6B62;
font-size:13px;
margin-top:2px;
  }

  @media (max-width: 520px){
body{ font-size:17px; }
h1{ font-size:2rem; }
.page{ padding:0 18px 72px; }
header.masthead{ flex-direction:column; align-items:flex-start; gap:6px; padding-top:28px; }
  }
